package com.oms.supplychain;

import com.oms.common.api.SharedCarrierClient;
import com.oms.supplychain.service.wms.*;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

class WmsCarrierBridgeTest {
    WmsOutboundServiceTest fixture;WmsCarrierBridge bridge;SharedCarrierClient remote;
    @BeforeAll static void start(){WmsOutboundServiceTest.setup();}
    @AfterAll static void stop(){WmsOutboundServiceTest.close();}
    @BeforeEach void setup() throws Exception {fixture=new WmsOutboundServiceTest();fixture.seed();fixture.setupWarehouse("QIMEN");fixture.jdbc.update("DELETE FROM wms_carrier_execution");fixture.jdbc.update("DELETE FROM wms_carrier_fact");bridge=new WmsCarrierBridge();remote=mock(SharedCarrierClient.class);ReflectionTestUtils.setField(bridge,"db",fixture.db);ReflectionTestUtils.setField(bridge,"carriers",remote);when(remote.options(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("rows",Collections.emptyList())));when(remote.convert(anyString(),anyMap(),anyString())).thenReturn(R.ok(resolved()));when(remote.fact(anyString(),anyMap(),anyString())).thenReturn(R.ok(resolved()));when(remote.freeze(anyString(),anyString(),anyMap(),anyString())).thenReturn(R.ok(resolved()));}
    @AfterEach void close(){fixture.stop();}
    Map<String,Object> resolved(){return map("available",true,"state","RESOLVED","standard_id",7,"external_code","001/sF.a");}
    Map<String,Object> task(){return map("return_sn","TEST_RETURN","business_sn","TEST_REFUND","business_type","REFUND_IN","owner_code","O1","real_store_code","R1","channel_id",3,"return_carrier","TM-SOURCE");}
    @Test void outboundChoiceUsesTrustedVirtualWarehouseContextAndPreservesExternalCode(){Map<String,Object> result=bridge.choose("QM","V",7,"北京市","OUTBOUND");assertEquals("001/sF.a",result.get("external_code"));ArgumentCaptor<Map> ctx=ArgumentCaptor.forClass(Map.class);verify(remote).convert(eq("QM"),ctx.capture(),anyString());assertEquals("WMS_OUTBOUND_CREATE",ctx.getValue().get("purpose"));assertEquals(String.valueOf(fixture.connection),ctx.getValue().get("connection_id"));assertEquals("北京",ctx.getValue().get("province"));}
    @Test void businessCannotSubmitAnArbitraryExternalCodeInsteadOfStandardIdentity(){assertThrows(IllegalArgumentException.class,()->bridge.choose("QM","V",0,"北京","OUTBOUND"));verifyNoInteractions(remote);}
    @Test void inboundFreezesSourceIdentificationAndTargetCodeForRetry(){Map<String,Object> task=task(),conn=map("id",1,"provider","QIMEN");assertEquals("001/sF.a",bridge.inbound("QM",task,conn).get("external_code"));when(remote.freeze(anyString(),anyString(),anyMap(),anyString())).thenReturn(R.ok(map("available",true,"external_code","CHANGED")));assertEquals("001/sF.a",bridge.inbound("QM",task,conn).get("external_code"));ArgumentCaptor<Map> incoming=ArgumentCaptor.forClass(Map.class);verify(remote,times(1)).fact(anyString(),incoming.capture(),anyString());assertEquals("CHANNEL_RETURN_IDENTIFY",((Map)incoming.getValue().get("context")).get("purpose"));verify(remote,times(1)).freeze(anyString(),anyString(),anyMap(),anyString());task.put("real_store_code","ANOTHER");assertThrows(IllegalArgumentException.class,()->bridge.inbound("QM",task,conn));}
    @Test void unknownInboundPreservesRawFactAndNeverFreezesOrContactsWarehouse(){Map<String,Object> task=task(),before=new LinkedHashMap<>(task);when(remote.fact(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("available",false,"state","MISSING","message","未识别")));assertThrows(IllegalArgumentException.class,()->bridge.inbound("QM",task,map("id",1,"provider","QIMEN")));assertEquals(before,task);verify(remote,never()).freeze(anyString(),anyString(),anyMap(),anyString());assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM wms_carrier_execution",Integer.class));}
    @Test void actualFactHasDurableOutboxBeforeRemoteServiceAndNetworkFailureOnlyChangesResolutionTask(){Map<String,Object> ctx=map("system_type","WMS","provider","QIMEN","purpose","WMS_OUTBOUND_ACTUAL","direction","IN","external_code","Unknown/001");bridge.fact("QM","PURCHASE_RETURN",1,"TEST_CGT","E1/P1",ctx);bridge.fact("QM","PURCHASE_RETURN",1,"TEST_CGT","E1/P1",ctx);bridge.fact("QM","PURCHASE_RETURN",1,"TEST_CGT","E1/P2",ctx);verifyNoInteractions(remote);assertEquals(2,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM wms_carrier_fact",Integer.class));when(remote.fact(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("unavailable"));bridge.resolveFacts("QM");assertEquals(2,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM wms_carrier_fact WHERE state='RETRY'",Integer.class));assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_receipt_event",Integer.class));}
    @Test void targetedMetadataRetryIsTenantScopedAndNeverCreatesAnOutboundEvent(){Map<String,Object> ctx=map("system_type","WMS","provider","QIMEN","purpose","WMS_OUTBOUND_ACTUAL","direction","IN","external_code","TEST-UNKNOWN");bridge.fact("QM","PURCHASE_RETURN",1,"TEST_CGT","TEST-P1",ctx);when(remote.fact(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("available",false,"state","MISSING","message","TEST missing")));bridge.resolveFacts("QM");assertThrows(IllegalArgumentException.class,()->bridge.retryFact("OTHER","PURCHASE_RETURN",1,"TEST-P1","TEST-UNKNOWN"));when(remote.fact(anyString(),anyMap(),anyString())).thenReturn(R.ok(resolved()));assertEquals(true,bridge.retryFact("QM","PURCHASE_RETURN",1,"TEST-P1","TEST-UNKNOWN").get("available"));int calls=mockingDetails(remote).getInvocations().size();bridge.retryFact("QM","PURCHASE_RETURN",1,"TEST-P1","TEST-UNKNOWN");assertEquals(calls,mockingDetails(remote).getInvocations().size());assertEquals(0,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM wms_outbound_receipt_event",Integer.class));}


    @Test void applicationContextActuallyRegistersTheDurableFactScheduler(){com.oms.common.tenant.TenantRouting tenants=mock(com.oms.common.tenant.TenantRouting.class);when(tenants.continuingCompanies()).thenReturn(Collections.emptySet());org.springframework.context.annotation.AnnotationConfigApplicationContext context=new org.springframework.context.annotation.AnnotationConfigApplicationContext();context.getBeanFactory().registerSingleton("tenants",tenants);context.getBeanFactory().registerSingleton("db",fixture.db);context.getBeanFactory().registerSingleton("carriers",remote);context.register(com.oms.common.carrier.CarrierBackground.class);context.registerBean("bridge",WmsCarrierBridge.class,()->new WmsCarrierBridge());try{context.refresh();assertEquals(1,context.getBean(org.springframework.scheduling.annotation.ScheduledAnnotationBeanPostProcessor.class).getScheduledTasks().size(),"declaration alone must not leave the outbox without a running scheduler");}finally{context.close();}}
}
